$p = 'X:\code\copilot-worktrees\P04\cirvine-msft-vigilant-telegram\assets\config.txt'
$bytes = [System.IO.File]::ReadAllBytes($p)
$text  = [System.Text.Encoding]::ASCII.GetString($bytes)

$ok = $true
$fail = @()

# CRLF check
if ($text -match "`r") { $ok=$false; $fail += 'Contains CR (CRLF) bytes' }

# Single trailing newline
if ($text.Length -eq 0 -or $text[-1] -ne "`n") { $ok=$false; $fail += 'Does not end with LF' }
if ($text.Length -ge 2 -and $text[-2] -eq "`n") { $ok=$false; $fail += 'Ends with blank 13th line / double newline' }

# Split content lines on LF; drop the final empty element produced by trailing LF
$parts = $text -split "`n", -1
if ($parts[-1] -ne '') { $ok=$false; $fail += 'No trailing newline element' }
$lines = $parts[0..($parts.Length-2)]

if ($lines.Count -ne 12) { $ok=$false; $fail += "Expected 12 content lines, got $($lines.Count)" }

for ($i=0; $i -lt $lines.Count; $i++) {
  $ln = $lines[$i]; $len = $ln.Length
  if ($len -lt 20 -or $len -gt 48) { $ok=$false; $fail += "Line $($i+1) length $len out of range" }
  if ($ln -match '^[A-Z0-9 +|/\\_*.#():=\-]+$') {} else { $ok=$false; $fail += "Line $($i+1) has disallowed chars" }
  if ($ln -match '[ \t]$') { $ok=$false; $fail += "Line $($i+1) has trailing whitespace" }
}

if ($text -notmatch 'CONFIG') { $ok=$false; $fail += 'Missing CONFIG substring' }

Write-Host '--- FILE CONTENT ---'
for ($i=0; $i -lt $lines.Count; $i++) { "{0,2}: [{1,2}] {2}" -f ($i+1), $lines[$i].Length, $lines[$i] }
Write-Host '--- VALIDATION ---'
if ($ok) { Write-Host 'SUCCESS: all assertions passed' } else { Write-Host 'FAILED:'; $fail | ForEach-Object { Write-Host " - $_" } }

